mapper.select:
SELECT * FROM student_answer a JOIN submit_test b ON a.submit_test_no = b.submit_test_no WHERE member_id = #{memberId}
AND b.homework_no = #{homeworkNo}
AND a.correct_or_wrong = 'C402'

mapper.insert:

	SELECT NVL(MAX(student_answer_no), 0) + 1
	FROM student_answer

INSERT INTO student_answer
	   (
			student_answer_no
			, submit_test_no
			, answer_no
			, correct_or_wrong
			, student_answer
	   )
VALUES (
			#{studentAnswerNo}
			, #{submitTestNo}
			, #{answerNo}
			, #{correctOrWrong}
			, #{studentAnswer}
	   )

mapper.update:
UPDATE student_answer


		correct_or_wrong = #{correctOrWrong}


		wrong_memo = #{wrongMemo}


WHERE student_answer_no = #{studentAnswerNo}

UPDATE student_answer
   SET wrong_memo = #{wrongMemo}
 WHERE student_answer_no = #{studentAnswerNo}

mapper.select:
SELECT * FROM (select rownum rn, tb.* from (
SELECT * FROM student_answer a JOIN submit_test b ON a.submit_test_no = b.submit_test_no JOIN test_bank c ON c.test_no = a.answer_no
order by b.submit_date DESC
) tb) WHERE rn BETWEEN #{startNo} AND #{endNo}

select test_answer, test_no, answer_no
from test_answer
where test_no=#{testNo}
